<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import { useRoute } from 'vue-router';
import { downloadFile, get, post } from '../api/client';
import { session } from '../api/session';
import { Button, Card, Field, Input, Select, EmptyState } from '../components/ui';
const { locale }=useI18n(),route=useRoute();
const l=(zh:string,en:string)=>locale.value.startsWith('zh')?zh:en;
interface Site {id:number;slug:string;label:string;engine:string;version:string;managed:string;status:string}
interface Evidence {id:string;requestId:string|null;createdAt:string;model:string|null;channelId:string|null;outcome:string;durationMs:number|null;firstTokenMs:number|null;charge:number|null;supplierCost:number|null;expectedCharge:number|null}
interface RecordRow {id:number;evidence:Evidence;signals:string[]}
interface Group {channelId:string|null;model:string|null;records:number;errorLogs:number|null;latestEvidenceAt:string;freshness:string;durationP95Ms:number|null;firstTokenP95Ms:number|null;durationSamples:number;firstTokenSamples:number;recordedCharge:number|null;chargeSamples:number;observedSupplierCost:number|null;costSamples:number;flagged:number}
interface Report {run:{status:string;nextPage:number;updatedAt:string;total:number;error:string|null}|null;groups:Group[];records:RecordRow[];sourceScope:string;sampleLimited:boolean;latestEvidenceAt:string|null}
interface Partner {id:number;siteId:number;kind:string;name:string;contact:string;notes:string;status:string;version:number}
interface Details {checks:string[];reference?:string;amount?:number;currency?:string;validFrom?:string;validTo?:string;receipt?:string}
interface Work {id:number;kind:string;title:string;description:string;priority:string;status:string;version:number;evidence:Evidence|null;details:Details;partnerId:number|null;ticketId:number|null;updatedAt:string}
interface Publication {siteId:number;version:number;title:string;body:string;state:string;published:boolean;token:string}
const sites=ref<Site[]>([]),checklists=ref<Record<string,string[]>>({}),siteId=ref<string|number|null>(null),tab=ref('quality');
const busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),report=ref<Report|null>(null),items=ref<Work[]>([]),partners=ref<Partner[]>([]),publication=ref<Publication|null>(null);
const day=ref(new Date(Date.now()+8*3600000).toISOString().slice(0,10)),requestId=ref(''),channel=ref(''),model=ref('');
const selected=ref<Work|null>(null),events=ref<{id:number;status:string;note:string;createdAt:string}[]>([]),historyLimited=ref(false),hasMore=ref(false);
const workKind=ref<string|number|null>('incident'),title=ref(''),description=ref(''),sourceId=ref<number|null>(null),partnerId=ref<string|number|null>(''),ticketId=ref(''),priority=ref<string|number|null>('normal');
const workNote=ref(''),workStatus=ref<string|number|null>('investigating'),checks=ref<string[]>([]),reference=ref(''),amount=ref<number|string>(''),currency=ref<string|number|null>('USD'),validFrom=ref(''),validTo=ref(''),receipt=ref('');
const partnerKind=ref<string|number|null>('supplier'),partnerName=ref(''),partnerContact=ref(''),partnerNotes=ref('');
const pubTitle=ref(''),pubBody=ref(''),pubState=ref<string|number|null>('maintenance'),pubPreview=ref(false);
const endpoint=ref(''),client=ref<string|number|null>('curl'),clientModel=ref(''),protocol=ref<string|number|null>('chat');
const autoCollection=ref(true),collectionInterval=ref(300000);
const currentSite=computed(()=>sites.value.find(s=>s.id===Number(siteId.value)));
const kinds=['incident','billing_review','maintenance','upgrade','recovery','quote','settlement','onboarding'];
const labels:Record<string,[string,string]>={quality:['质量与费用','Quality & cost'],work:['事件与交付','Cases & delivery'],partners:['渠道合作','Partners'],portal:['客户接入与公告','Client setup & status'],
 incident:['故障事件','Incident'],billing_review:['费用复核','Billing review'],maintenance:['维护计划','Maintenance'],upgrade:['升级交付','Upgrade'],recovery:['恢复演练','Recovery'],quote:['报价记录','Quote'],settlement:['结算事项','Settlement'],onboarding:['客户接入','Onboarding'],
 open:['待处理','Open'],investigating:['处理中','In progress'],waiting:['等待材料','Waiting'],resolved:['已验证','Verified'],closed:['已关闭','Closed'],cancelled:['已取消','Cancelled'],
 normal:['普通','Normal'],urgent:['紧急','Urgent'],supplier:['上游供应商','Supplier'],reseller:['下游代理','Reseller'],operator:['代运维','Service operator'],active:['合作中','Active'],archived:['已归档','Archived'],
 pending:['尚未采集','Pending'],partial:['部分日志已读取','Partial'],complete:['本轮日志读取结束','Scan complete'],changed:['源日志变化，需重新采集','Source changed; restart'],error:['采集失败','Collection failed'],unsupported:['接口暂不兼容','Unsupported'],
 recorded_error:['错误日志','Error log'],charge_difference:['记录计费差异','Charge discrepancy'],below_supplier_cost:['记录收入低于成本','Charge below cost'],
 scope:['确认影响范围','Confirm scope'],evidence:['收集诊断证据','Collect evidence'],mitigation:['记录处理措施','Record mitigation'],verification:['验证并记录结果','Verify and record result'],
 source:['核对原始记录','Check source'],rate:['核对历史费率','Check historical rates'],supplier_check:['核对上游账单','Check supplier invoice'],decision:['记录复核结论','Record decision'],notice:['安排维护通知','Prepare notice'],backup:['确认业务备份','Verify business backup'],compatibility:['检查版本兼容','Check compatibility'],migration:['检查数据库迁移','Review DB migrations'],rollback:['确认回退边界','Review rollback limits'],
 backup_scope:['核对备份范围','Verify backup scope'],checksum:['校验备份文件','Verify checksum'],encryption_key:['确认恢复所需密钥','Verify recovery keys'],isolated_restore:['隔离环境恢复','Restore in isolation'],business_verification:['核对业务数据与功能','Verify data and behavior'],currency:['确认金额和币种','Check amount and currency'],validity:['确认报价有效期','Check quote validity'],acceptance:['记录报价接受依据','Record acceptance'],adjustments:['核对退款及调整','Check adjustments'],receipt:['核对真实支付回执','Verify payment receipt'],reconciliation:['记录对账结论','Record reconciliation'],endpoint:['核对接入地址','Verify endpoint'],protocol:['核对协议','Verify protocol'],model:['核对模型权限','Verify model access'],client_config:['生成客户端配置','Generate client setup'],customer_verification:['记录客户验证结果','Record customer verification']};
const label=(key:string)=>{const x=labels[key];return x?l(x[0],x[1]):key;};
const options=(values:string[])=>values.map(value=>({value,label:label(value)}));
const transitions:Record<string,string[]>={open:['open','investigating','waiting','cancelled'],investigating:['investigating','waiting','resolved','cancelled'],waiting:['waiting','investigating','resolved','cancelled'],resolved:['resolved','closed','investigating'],closed:['closed','investigating'],cancelled:['cancelled','open']};
const number=(value:number|null|undefined)=>value==null?'—':value.toLocaleString(undefined,{maximumFractionDigits:6});
async function action(fn:()=>Promise<void>) {busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=String(e);}finally{busy.value=false;}}
let loadEpoch=0;
async function load() {
  if(!siteId.value)return;const epoch=++loadEpoch;loading.value=true;
  try{const sid=Number(siteId.value),q=new URLSearchParams({siteId:String(sid),day:day.value});
    if(requestId.value.trim())q.set('requestId',requestId.value.trim());if(channel.value.trim())q.set('channelId',channel.value.trim());if(model.value.trim())q.set('model',model.value.trim());
    const [r,w,p,pub,settings]=await Promise.all([get<Report>(`/api/services/quality?${q}`),get<{items:Work[];hasMore:boolean}>(`/api/services/work?siteId=${sid}`),get<{items:Partner[]}>(`/api/services/partners?siteId=${sid}`),get<{item:Publication|null}>(`/api/services/publication?siteId=${sid}`),get<{enabled:boolean;intervalMs:number}>(`/api/services/collection-settings?siteId=${sid}`)]);
    if(epoch!==loadEpoch)return;report.value=r;items.value=w.items;hasMore.value=w.hasMore;partners.value=p.items;publication.value=pub.item;
    pubTitle.value=pub.item?.title??currentSite.value?.label??'';pubBody.value=pub.item?.body??'';pubState.value=pub.item?.state??'maintenance';
    autoCollection.value=settings.enabled;collectionInterval.value=settings.intervalMs;
  }finally{if(epoch===loadEpoch)loading.value=false;}
}
onMounted(()=>void action(async()=>{const result=await get<{sites:Site[];checklists:Record<string,string[]>}>('/api/services/catalog');sites.value=result.sites;checklists.value=result.checklists;if(sites.value[0])siteId.value=sites.value.find(s=>String(s.id)===route.query.site)?.id??sites.value[0].id;}));
watch(siteId,()=>{report.value=null;items.value=[];partners.value=[];publication.value=null;selected.value=null;events.value=[];sourceId.value=null;partnerId.value='';ticketId.value='';title.value='';description.value='';requestId.value='';channel.value='';model.value='';pubPreview.value=false;void action(load);});
async function collect(){await action(async()=>{await post('/api/services/collect',{siteId:Number(siteId.value),day:day.value});await load();});}
async function toggleCollection(){await action(async()=>{await post('/api/services/collection-settings',{siteId:Number(siteId.value),enabled:!autoCollection.value});await load();});}
async function openWork(item:Work){await action(async()=>{const r=await get<{item:Work;events:typeof events.value;historyLimited:boolean}>(`/api/services/work/${item.id}`);selected.value=r.item;events.value=r.events;historyLimited.value=r.historyLimited;workStatus.value=r.item.status==='open'?'investigating':r.item.status;workNote.value='';
  const d=r.item.details;checks.value=[...(d.checks??[])];reference.value=d.reference??'';amount.value=d.amount??'';currency.value=d.currency??'USD';validFrom.value=d.validFrom??'';validTo.value=d.validTo??'';receipt.value=d.receipt??'';});}
function fromRecord(r:RecordRow){sourceId.value=r.id;workKind.value=r.signals.includes('recorded_error')?'incident':'billing_review';title.value=`${label(String(workKind.value))} · ${r.evidence.model??r.evidence.id}`;description.value=`${r.evidence.createdAt}\n${r.evidence.requestId??r.evidence.id}\n${r.signals.map(label).join(' / ')}`;tab.value='work';selected.value=null;}
async function createWork(){await action(async()=>{const r=await post<{item:Work}>('/api/services/work',{siteId:Number(siteId.value),kind:workKind.value,title:title.value,description:description.value,priority:priority.value,...(sourceId.value?{sourceId:sourceId.value}:{}),...(partnerId.value?{partnerId:Number(partnerId.value)}:{}),...(ticketId.value?{ticketId:Number(ticketId.value)}:{})});title.value='';description.value='';sourceId.value=null;await load();notice.value=l(`已建立事项 #${r.item.id}`,`Created case #${r.item.id}`);});}
async function updateWork(){if(!selected.value)return;await action(async()=>{const details:Details={checks:checks.value,reference:reference.value,receipt:receipt.value};if(amount.value!==''){details.amount=Number(amount.value);details.currency=String(currency.value);}if(validFrom.value||validTo.value){details.validFrom=validFrom.value;details.validTo=validTo.value;}
  const r=await post<{item:Work}>(`/api/services/work/${selected.value!.id}/events`,{version:selected.value!.version,status:workStatus.value,note:workNote.value,details});await load();selected.value=r.item;workNote.value='';const history=await get<{events:typeof events.value;historyLimited:boolean}>(`/api/services/work/${r.item.id}`);events.value=history.events;historyLimited.value=history.historyLimited;});}
async function moreWork(){await action(async()=>{const last=items.value.at(-1);if(!last)return;const r=await get<{items:Work[];hasMore:boolean}>(`/api/services/work?siteId=${siteId.value}&beforeId=${last.id}`);items.value.push(...r.items);hasMore.value=r.hasMore;});}
async function addPartner(){await action(async()=>{await post('/api/services/partners',{siteId:Number(siteId.value),kind:partnerKind.value,name:partnerName.value,contact:partnerContact.value,notes:partnerNotes.value});partnerName.value='';partnerContact.value='';partnerNotes.value='';await load();});}
async function archivePartner(p:Partner){await action(async()=>{await post(`/api/services/partners/${p.id}`,{kind:p.kind,name:p.name,contact:p.contact,notes:p.notes,status:p.status==='active'?'archived':'active',version:p.version});await load();});}
async function publish(published:boolean){await action(async()=>{await post('/api/services/publication',{siteId:Number(siteId.value),version:publication.value?.version??0,title:pubTitle.value,body:pubBody.value,state:pubState.value,published});await load();notice.value=published?l('公告已发布','Status notice published'):l('公告已撤回或保存为草稿','Notice unpublished or saved as draft');});}
async function download(url: string, name: string) { await action(() => downloadFile(url, name)); }
function qualityExport(){const q=new URLSearchParams({siteId:String(siteId.value),day:day.value});if(requestId.value.trim())q.set('requestId',requestId.value.trim());if(channel.value.trim())q.set('channelId',channel.value.trim());if(model.value.trim())q.set('model',model.value.trim());void download(`/api/services/quality.csv?${q}`,'observed-evidence.csv');}
// This generator never receives a real API key and never sends a model request.
const configText=computed(()=>{let url:URL;try{url=new URL(endpoint.value);if(!['https:','http:'].includes(url.protocol)||url.username||url.password||url.search||url.hash)return '';}catch{return '';}
  if(!clientModel.value.trim()||/[\r\n]/.test(clientModel.value))return '';const base=url.href.replace(/\/$/,''),path=protocol.value==='responses'?'/responses':'/chat/completions';
  const shellQuote=(v:string)=>"'"+v.replace(/'/g,"'\\''")+"'";
  if(client.value==='environment')return `OPENAI_BASE_URL=${shellQuote(base)}\nOPENAI_API_KEY=REPLACE_WITH_YOUR_KEY\nMODEL=${shellQuote(clientModel.value)}`;
  if(client.value==='python')return `import os\nfrom openai import OpenAI\nclient = OpenAI(base_url=${JSON.stringify(base)}, api_key=os.environ["OPENAI_API_KEY"])\n${protocol.value==='responses'?`response = client.responses.create(model=${JSON.stringify(clientModel.value)}, input="Hello")`:`response = client.chat.completions.create(model=${JSON.stringify(clientModel.value)}, messages=[{"role":"user","content":"Hello"}])`}\nprint(response)`;
  const quote=(v:string)=>"'"+v.replace(/'/g,"'\\''")+"'";const payload=protocol.value==='responses'?{model:clientModel.value,input:'Hello',max_output_tokens:16}:{model:clientModel.value,messages:[{role:'user',content:'Hello'}],max_tokens:16};
  return `curl ${quote(base+path)} \\\n  -H 'Content-Type: application/json' \\\n  -H "Authorization: Bearer $OPENAI_API_KEY" \\\n  --data ${quote(JSON.stringify(payload))}`;});
async function copyConfig(){await action(async()=>{await navigator.clipboard.writeText(configText.value);notice.value=l('配置已复制；运行会产生实际 API 调用','Copied. Running this example makes an actual API call.');});}
</script>

<template><div class="rp-page space-y-5">
  <RouterLink :to="{path:'/knowledge',query:siteId?{site:String(siteId)}:{}}" class="text-sm text-accent">{{l('客户知识库：维护接入指南与模型兼容性说明','Customer knowledge: setup guides and model compatibility')}} →</RouterLink>
  <RouterLink v-if="session.state.user?.role!=='viewer'" :to="{path:'/collaboration',query:{mode:'manage',...(siteId?{site:String(siteId)}:{})}}" class="text-sm text-accent">{{l('协作工作台：邀请伙伴与岗位协作者','Collaboration: invite partners and specialists')}} →</RouterLink>
  <div><p class="text-xs uppercase tracking-widest text-accent">SERVICE CENTER</p><h1 class="mt-1 text-xl font-semibold">{{l('站点服务中心','Site service center')}}</h1><p class="mt-2 max-w-3xl text-sm leading-6 text-muted">{{l('从真实请求中发现问题，把质量、费用、合作和运维处理连接起来。只检索已有日志，不额外调用模型进行心跳测试。','Use existing request evidence to connect quality, costs, partners and operational work. Collection reads logs and never generates model probes.')}}</p></div>
  <p v-if="error" role="alert" class="rounded border border-red/30 bg-red/10 p-3 text-sm text-red">{{error}}</p><p v-if="notice" role="status" class="text-sm text-accent">{{notice}}</p>
  <EmptyState v-if="!sites.length&&!busy" :title="l('先接入一个站点','Connect a site to begin')" />
  <template v-if="sites.length">
    <div class="grid gap-3 sm:grid-cols-[minmax(220px,1fr)_auto] sm:items-end"><Field :label="l('当前站点','Current site')"><Select v-model="siteId" :disabled="busy||loading" :options="sites.map(s=>({value:s.id,label:s.label+' · '+s.engine}))" /></Field><p class="pb-2 text-xs text-muted">{{currentSite?.version}} · {{currentSite?.managed==='compose'?l('本机管理','Local management'):l('已有站点','Connected site')}}</p></div>
    <nav class="flex flex-wrap gap-2" :aria-label="l('服务模块','Service modules')"><Button v-for="key in ['quality','work','partners','portal']" :key="key" :variant="tab===key?'primary':'outline'" @click="tab=key">{{label(key)}}</Button></nav>
    <div v-if="tab==='quality'" class="space-y-4">
      <div class="flex flex-wrap items-center gap-3 text-xs text-muted"><span>{{l('后台读取今日已有日志','Background reads of today’s existing logs')}}：{{collectionInterval===0?l('全局关闭','Globally disabled'):autoCollection?l('已启用','Enabled'):l('已暂停','Paused')}} · {{collectionInterval?`${Math.max(1,Math.round(collectionInterval/60000))} min`: '—'}}</span><Button v-if="session.canWrite.value&&collectionInterval>0" size="sm" :loading="busy" @click="toggleCollection">{{autoCollection?l('暂停自动采集','Pause collection'):l('启用自动采集','Enable collection')}}</Button></div>
      <Card><form class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4" @submit.prevent="action(load)"><Field :label="l('日期（北京时间，保留30天）','Day (Asia/Shanghai; 30-day retention)')"><Input v-model="day" type="date" required /></Field><Field :label="l('请求编号（精确匹配）','Request ID (exact match)')"><Input v-model="requestId" /></Field><Field :label="l('上游账号 / 渠道编号','Upstream account / channel ID')"><Input v-model="channel" /></Field><Field :label="l('模型（精确匹配）','Model (exact match)')"><Input v-model="model" /></Field><div class="flex flex-wrap gap-2 sm:col-span-2 lg:col-span-4"><Button type="submit" :loading="loading">{{l('查询已有证据','Search stored evidence')}}</Button><Button v-if="session.canWrite.value" :loading="busy" :disabled="currentSite?.status!=='active'" @click="collect">{{l('读取下一批已有日志','Read next log batch')}}</Button><Button :disabled="!report?.records.length" @click="qualityExport">{{l('导出证据 CSV','Export evidence CSV')}}</Button></div></form></Card>
      <div class="grid gap-3 sm:grid-cols-3"><Card><p class="text-xs text-muted">{{l('采集状态','Collection')}}</p><p class="mt-2 font-medium">{{label(report?.run?.status??'pending')}}</p><p class="mt-2 text-xs text-muted">{{report?.run?.updatedAt??'—'}} UTC</p></Card><Card><p class="text-xs text-muted">{{l('最近真实请求','Latest recorded request')}}</p><p class="mt-2 break-all text-sm">{{report?.latestEvidenceAt??l('暂无观测证据','No observed evidence')}}</p><p class="mt-2 text-xs text-muted">{{l('没有请求不代表正常或故障','No traffic does not establish health or failure')}}</p></Card><Card><p class="text-xs text-muted">{{l('来源覆盖','Source coverage')}}</p><p class="mt-2 text-sm">{{report?.sourceScope==='consumption-only'?l('消费记录；不覆盖所有失败','Consumption logs; failures not fully covered'):report?.sourceScope==='consume-and-error-logs'?l('消费及错误日志；不代表全部调用','Consume and error logs; not all calls'):l('暂无可用数据','No data available')}}</p></Card></div>
      <p v-if="report?.run?.error" class="text-sm text-amber">{{report.run.error}}</p>
      <p class="text-xs leading-5 text-muted">{{l('指标仅描述已读取的日志样本。未知字段显示 —，不计算全站成功率或 SLA。费用差异是复核线索，不是欠款或漏洞结论。管理日志检索仍消耗少量网络与数据库资源。','Metrics describe collected log samples only. Unknown fields show —. No global success rate or SLA is inferred. Cost differences are review signals, not debt or proof of a vulnerability. Log retrieval still uses network and database resources.')}}</p>
      <p v-if="report?.sampleLimited" class="text-sm text-amber">{{l('当前统计达到10000条样本上限，请按渠道或模型筛选。','The 10,000-record sample cap was reached. Filter by channel or model.')}}</p>
      <Card><template #title>{{l('渠道与模型观测','Channel and model observations')}}</template><div class="overflow-x-auto"><table class="w-full text-left text-xs"><thead><tr><th>{{l('渠道 / 模型','Channel / model')}}</th><th>{{l('样本 / 错误日志','Samples / errors')}}</th><th>{{l('耗时 P95 / 覆盖','Duration P95 / coverage')}}</th><th>{{l('首字 P95 / 覆盖','First token P95 / coverage')}}</th><th>{{l('记账 / 上游成本 USD','Charge / supplier USD')}}</th><th>{{l('异常线索','Signals')}}</th></tr></thead><tbody><tr v-for="g in report?.groups" :key="JSON.stringify([g.channelId,g.model])"><td class="max-w-56 break-words">{{g.channelId??'—'}} / {{g.model??'—'}}<p class="mt-1 text-muted">{{g.freshness==='recent'?l('近期证据','Recent evidence'):l('历史证据','Historical evidence')}}</p></td><td>{{g.records}} / {{number(g.errorLogs)}}</td><td>{{number(g.durationP95Ms)}} ms · {{g.durationSamples}}/{{g.records}}</td><td>{{number(g.firstTokenP95Ms)}} ms · {{g.firstTokenSamples}}/{{g.records}}</td><td>{{number(g.recordedCharge)}} / {{number(g.observedSupplierCost)}}<p class="text-muted">{{l('覆盖','Coverage')}} {{g.chargeSamples}} / {{g.costSamples}}</p></td><td>{{g.flagged}}</td></tr></tbody></table></div><EmptyState v-if="!report?.groups.length" :title="l('该日期或筛选条件没有证据','No evidence for this date or filter')" /></Card>
      <Card><template #title>{{l('请求诊断（最多展示200条）','Request diagnostics (up to 200 shown)')}}</template><div class="space-y-3"><div v-for="r in report?.records" :key="r.id" class="rounded-lg border border-border p-3 text-xs"><div class="flex flex-wrap justify-between gap-2"><p class="min-w-0 break-all font-mono">{{r.evidence.requestId??r.evidence.id}}</p><Button v-if="session.canWrite.value" size="sm" @click="fromRecord(r)">{{l('建立处理事项','Create case')}}</Button></div><p class="mt-2 break-words text-muted">{{r.evidence.createdAt}} · {{r.evidence.model??'—'}} · {{r.evidence.outcome}} · {{number(r.evidence.durationMs)}} ms</p><p class="mt-1">{{l('记录扣费 / 上游成本 / 按记录倍率估算','Charge / supplier cost / estimated charge')}}：{{number(r.evidence.charge)}} / {{number(r.evidence.supplierCost)}} / {{number(r.evidence.expectedCharge)}} USD</p><p v-if="r.signals.length" class="mt-1 text-amber">{{r.signals.map(label).join(' · ')}}</p></div></div></Card>
    </div>
    <div v-if="tab==='work'" class="space-y-4">
      <Card v-if="session.canWrite.value"><template #title>{{l('建立事件或交付事项','New case or delivery task')}}</template><form class="grid gap-3 sm:grid-cols-2" @submit.prevent="createWork"><Field :label="l('事项类型','Type')"><Select v-model="workKind" :options="options(kinds)" /></Field><Field :label="l('优先级','Priority')"><Select v-model="priority" :options="options(['normal','urgent'])" /></Field><Field :label="l('标题','Title')"><Input v-model="title" minlength="3" maxlength="160" required /></Field><Field :label="l('关联伙伴（可选）','Partner (optional)')"><Select v-model="partnerId" :options="[{value:'',label:l('不关联','None')},...partners.filter(p=>p.status==='active').map(p=>({value:p.id,label:p.name}))]" /></Field><Field :label="l('关联支持工单编号（可选）','Support ticket ID (optional)')"><Input v-model="ticketId" type="number" min="1" /></Field><p v-if="sourceId" class="self-end text-xs text-accent">{{l('已关联请求证据','Request evidence attached')}} #{{sourceId}} <button type="button" @click="sourceId=null">×</button></p><Field class="sm:col-span-2" :label="l('影响范围、现象与处理目标','Scope, symptoms and desired outcome')"><textarea v-model="description" class="editor" rows="3" minlength="5" maxlength="4000" required /></Field><p class="text-xs text-muted sm:col-span-2">{{l('请勿填写密码、密钥或完整客户请求。事项用于协作记录，不会自动操作引擎或转账。','Do not include secrets or complete customer prompts. Cases record work; they do not execute engine commands or transfer money.')}}</p><Button type="submit" :loading="busy">{{l('创建事项','Create case')}}</Button></form></Card>
      <div class="grid gap-4 xl:grid-cols-2"><Card><template #title>{{l('处理清单','Work queue')}}</template><button v-for="w in items" :key="w.id" class="block w-full border-b border-border py-3 text-left text-sm" @click="openWork(w)"><p class="break-words">#{{w.id}} {{w.title}}</p><p class="mt-1 text-xs text-muted">{{label(w.kind)}} · {{label(w.status)}} · {{w.updatedAt}} UTC</p></button><EmptyState v-if="!items.length" :title="l('暂无事项','No cases yet')" /><Button v-if="hasMore" class="mt-3" @click="moreWork">{{l('加载更多','Load more')}}</Button></Card>
      <Card v-if="selected"><template #title>#{{selected.id}} {{selected.title}}</template><div class="space-y-4 text-sm"><p class="whitespace-pre-wrap break-words">{{selected.description}}</p><p class="text-xs text-muted">{{label(selected.kind)}} · {{label(selected.status)}}<span v-if="selected.ticketId"> · {{l('支持工单','Support ticket')}} #{{selected.ticketId}}</span></p><p v-if="selected.evidence" class="break-all text-xs text-muted">{{l('证据快照','Evidence snapshot')}}：{{selected.evidence.requestId??selected.evidence.id}} · {{selected.evidence.createdAt}}</p><Button size="sm" @click="download(`/api/services/work/${selected.id}/export`,`service-case-${selected.id}.json`)">{{l('导出内部诊断记录','Export internal case record')}}</Button>
        <form v-if="session.canWrite.value" class="space-y-3" @submit.prevent="updateWork"><div class="grid gap-2 sm:grid-cols-2"><label v-for="c in checklists[selected.kind]" :key="c" class="flex items-start gap-2 text-xs"><input v-model="checks" type="checkbox" :value="c" />{{label(c==='supplier'?'supplier_check':c)}}</label></div><p class="text-xs text-muted">{{l('勾选表示你已完成检查；在处理说明中记录证据。','Check items only after completing them; record evidence below.')}}</p><template v-if="['quote','settlement','billing_review'].includes(selected.kind)"><div class="grid gap-3 sm:grid-cols-2"><Field :label="l('金额（可选）','Amount (optional)')"><Input v-model="amount" type="number" min="0" step="0.000001" /></Field><Field :label="l('币种','Currency')"><Select v-model="currency" :options="['USD','CNY','EUR','USDT'].map(value=>({value,label:value}))" /></Field></div><Field :label="l('单据编号 / 依据','Document reference')"><Input v-model="reference" maxlength="200" /></Field><Field v-if="selected.kind==='settlement'" :label="l('真实支付渠道回执（完成时必填）','Actual provider receipt (required to complete)')"><Input v-model="receipt" maxlength="200" /></Field><div v-if="selected.kind==='quote'" class="space-y-3"><Field :label="l('生效时间（ISO，含时区）','Valid from (ISO with offset)')"><Input v-model="validFrom" placeholder="2026-10-22T00:00:00+08:00" /></Field><Field :label="l('截止时间（ISO，含时区）','Valid until (ISO with offset)')"><Input v-model="validTo" placeholder="2026-11-22T00:00:00+08:00" /></Field></div></template><Field :label="l('状态','Status')"><Select v-model="workStatus" :options="options(transitions[selected.status]??[])" /></Field><Field :label="l('处理说明与验证依据','Update and verification evidence')"><textarea v-model="workNote" class="editor" rows="3" minlength="5" maxlength="4000" required /></Field><Button type="submit" :loading="busy">{{l('记录进展','Record progress')}}</Button></form>
        <div v-for="e in events" :key="e.id" class="border-l-2 border-border pl-3"><p class="text-xs text-muted">{{label(e.status)}} · {{e.createdAt}} UTC</p><p class="mt-1 whitespace-pre-wrap break-words">{{e.note}}</p></div><p v-if="historyLimited" class="text-xs text-muted">{{l('显示最近200条，完整记录请导出。','Latest 200 events shown; export for more.')}}</p>
      </div></Card></div>
      <Card><template #title>{{l('环境与运维入口','Environment & operations')}}</template><p class="text-sm text-muted">{{l('升级、维护、恢复演练使用上方交付事项留存检查结果。面板备份不等于引擎业务数据备份，回退程序版本也不保证数据库迁移可逆。','Use delivery cases above to record upgrade, maintenance and recovery evidence. Panel backups do not include engine data, and a binary rollback does not reverse database migrations.')}}</p><div class="mt-3 flex flex-wrap gap-4 text-sm text-accent"><RouterLink to="/self-deploy">{{l('本机环境与应用管理','Local environment & apps')}}</RouterLink><RouterLink :to="`/sites/${currentSite?.slug}`">{{l('站点管理','Site management')}}</RouterLink><RouterLink v-if="session.isRoot.value" to="/admin/operations">{{l('面板备份与运行状态','Panel backups & operations')}}</RouterLink></div></Card>
    </div>
    <div v-if="tab==='partners'" class="space-y-4"><Card v-if="session.canWrite.value"><template #title>{{l('新增合作伙伴','Add a partner')}}</template><form class="grid gap-3 sm:grid-cols-2" @submit.prevent="addPartner"><Field :label="l('合作身份','Partner role')"><Select v-model="partnerKind" :options="options(['supplier','reseller','operator'])" /></Field><Field :label="l('名称','Name')"><Input v-model="partnerName" required maxlength="120" /></Field><Field :label="l('联系信息（可选）','Contact (optional)')"><Input v-model="partnerContact" maxlength="200" /></Field><Field :label="l('合作范围与备注','Scope and notes')"><Input v-model="partnerNotes" maxlength="2000" /></Field><Button type="submit" :loading="busy">{{l('保存伙伴','Save partner')}}</Button></form></Card><p class="text-xs text-muted">{{l('伙伴档案属于当前站点工作区，不自动授予登录权限。报价、结算与交付可在“事件与交付”中关联伙伴。','Partner records belong to this site workspace and grant no login permissions. Link quotes, settlements and delivery cases in the work queue.')}}</p><div class="grid gap-4 md:grid-cols-2"><Card v-for="p in partners" :key="p.id"><template #title>{{p.name}}</template><div class="space-y-2 text-sm"><p>{{label(p.kind)}} · {{label(p.status)}}</p><p class="break-words text-muted">{{p.contact}}</p><p class="whitespace-pre-wrap break-words">{{p.notes}}</p><div class="flex gap-2"><Button v-if="session.canWrite.value" size="sm" @click="partnerId=p.id;workKind='quote';tab='work'">{{l('关联新事项','New linked case')}}</Button><Button v-if="session.canWrite.value" size="sm" @click="archivePartner(p)">{{p.status==='active'?l('归档','Archive'):l('恢复合作','Reactivate')}}</Button></div></div></Card></div><EmptyState v-if="!partners.length" :title="l('暂无合作伙伴','No partners yet')" /></div>
    <div v-if="tab==='portal'" class="space-y-4"><Card><template #title>{{l('客户端配置向导','Client configuration guide')}}</template><div class="grid gap-3 sm:grid-cols-2"><Field :label="l('完整 API 基础地址（通常以 /v1 结尾）','API base URL (usually ending in /v1)')"><Input v-model="endpoint" placeholder="https://api.example.com/v1" /></Field><Field :label="l('站点允许的模型名称','Model enabled by the site')"><Input v-model="clientModel" /></Field><Field :label="l('客户端示例','Client example')"><Select v-model="client" :options="[{value:'curl',label:'cURL'},{value:'python',label:'Python SDK'},{value:'environment',label:l('环境变量','Environment variables')}]" /></Field><Field :label="l('协议（需站点支持）','Protocol (must be supported by site)')"><Select v-model="protocol" :options="[{value:'chat',label:'Chat Completions'},{value:'responses',label:'Responses'}]" /></Field></div><p class="my-3 text-xs text-muted">{{l('不需要在面板填写客户密钥。示例不会自动执行，运行时会产生真实调用及费用。模型能力和协议兼容性需以站点实际支持为准。','No customer API key is collected here. Examples are not executed automatically; running them makes a billable request. Verify model and protocol support with the site.')}}</p><pre v-if="configText" class="overflow-x-auto rounded bg-panel-2 p-3 text-xs">{{configText}}</pre><Button class="mt-3" :disabled="!configText" @click="copyConfig">{{l('复制配置示例','Copy configuration')}}</Button></Card>
      <Card><template #title>{{l('对外状态公告','Public status notice')}}</template><p class="mb-3 text-xs text-muted">{{l('公开页面只展示下方手工填写的内容，不包含请求、费用、伙伴或服务器数据。请先预览，再明确发布；状态是站长声明。','The public page shows only the text entered below. Requests, costs, partners and server data are excluded. Preview before publishing; status is an operator statement.')}}</p><div class="space-y-3"><Field :label="l('公开标题','Public title')"><Input v-model="pubTitle" maxlength="100" :disabled="!session.canWrite.value" /></Field><Field :label="l('对外状态','Public state')"><Select v-model="pubState" :disabled="!session.canWrite.value" :options="[{value:'operational',label:l('服务正常（人工声明）','Operational (manual statement)')},{value:'degraded',label:l('服务异常','Degraded')},{value:'maintenance',label:l('计划维护','Maintenance')}]" /></Field><Field :label="l('公开说明','Public message')"><textarea v-model="pubBody" :disabled="!session.canWrite.value" class="editor" rows="4" minlength="5" maxlength="4000" /></Field><Button @click="pubPreview=!pubPreview">{{l('预览公开内容','Preview public content')}}</Button><div v-if="pubPreview" class="rounded border border-border bg-panel-2 p-4"><h2 class="font-semibold">{{pubTitle}}</h2><p class="my-2 text-xs text-muted">{{pubState}}</p><p class="whitespace-pre-wrap break-words text-sm">{{pubBody}}</p></div><div v-if="session.canWrite.value" class="flex flex-wrap gap-2"><Button :loading="busy" :disabled="!pubPreview||pubBody.trim().length<5" variant="primary" @click="publish(true)">{{l('发布以上内容','Publish this content')}}</Button><Button :loading="busy" :disabled="pubBody.trim().length<5" @click="publish(false)">{{l('保存草稿 / 撤回公开页面','Save draft / unpublish')}}</Button></div><a v-if="publication?.published" :href="`/public/service/${publication.token}`" target="_blank" rel="noopener noreferrer" class="block break-all text-sm text-accent">{{l('查看已发布公告','View published notice')}} ↗</a></div></Card>
    </div>
  </template>
</div></template>
