.editor{width:100%;border:1px solid var(--color-border,var(--glass-border));border-radius:8px;background:var(--color-panel-2,transparent);padding:10px;font-size:13px}th,td{padding:12px 10px;border-bottom:1px solid var(--glass-border);vertical-align:top}th{font-weight:500;color:var(--color-muted,#8994a7);white-space:nowrap}
</style>
